package vn.covie.notifications.application; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.*; import org.springframework.data.domain.PageRequest; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.covie.auth.security.CurrentActorProvider; import vn.covie.notifications.api.dto.*; import vn.covie.notifications.model.NotificationEntity; import vn.covie.notifications.persistence.NotificationRepository; import vn.covie.shared.time.AppClock; import vn.covie.shared.web.*;
@Service public class NotificationReadService { private final NotificationRepository notifications; private final CurrentActorProvider actors; private final NotificationCursorCodec cursors; private final ObjectMapper json; private final AppClock clock; public NotificationReadService(NotificationRepository n,CurrentActorProvider a,NotificationCursorCodec c,ObjectMapper j,AppClock clock){notifications=n;actors=a;cursors=c;json=j;this.clock=clock;}
 public NotificationPageResponse inbox(Integer requested,String encoded){int limit=requested==null?20:requested;if(limit<1||limit>50)throw new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.UNPROCESSABLE_ENTITY,"Notification limit must be between 1 and 50.");var actor=actors.currentActor();var cursor=cursors.decode(encoded);var rows=notifications.page(actor.userId(),cursor==null?null:cursor.createdAt(),cursor==null?null:cursor.notificationId(),PageRequest.of(0,limit+1));boolean more=rows.size()>limit;if(more)rows=rows.subList(0,limit);String next=more?cursors.encode(new NotificationCursor(rows.getLast().getCreatedAt(),rows.getLast().getId())):null;return new NotificationPageResponse(rows.stream().map(this::map).toList(),next); }
 @Transactional public void markRead(UUID id){UUID user=actors.currentActor().userId();notifications.markRead(id,user,clock.now());if(notifications.findByIdAndUserId(id,user).isEmpty())throw notFound();} @Transactional public void markAllRead(){notifications.markAllRead(actors.currentActor().userId(),clock.now());}
 private NotificationResponse map(NotificationEntity n){try{return new NotificationResponse(n.getId(),n.getNotificationType(),n.getPayload()==null?Map.of():json.convertValue(n.getPayload(),new TypeReference<Map<String,Object>>(){}),n.getReadAt()!=null,n.getCreatedAt());}catch(IllegalArgumentException e){throw new IllegalStateException("Notification payload is invalid.",e);}} private static ApiException notFound(){return new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Resource not found.");}}
